class TestCase_13(ATTestCase.TestCase):
    testCaseDesc = "On the copper test port now running with an automatically resolved role, record the resolved polarity from 'show interface <port>' and the polarity configuration from 'show running-config interface <port>'. Then apply 'interface <port>', 'shutdown', wait for the port to go down, apply 'no shutdown' and wait for the link to return."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "On the copper test port now running with an automatically resolved role, record the resolved polarity from 'show interface <port>' and the polarity configuration from 'show running-config interface <port>'. Then apply 'interface <port>', 'shutdown', wait for the port to go down, apply 'no shutdown' and wait for the link to return.\n"
    testCaseMethod += "Verify: 'show interface <port> status' shows the port going out of 'connected' after shutdown and returning to 'connected' after no shutdown; 'show interface <port>' then reports the same resolved current polarity value recorded before the cycle; 'show running-config interface <port>' shows the polarity configuration unchanged.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Establish the "automatically resolved role" precondition: leave portA at its
        # defaults (speed auto, duplex auto, polarity auto) so MDI/MDI-X is resolved by
        # auto-negotiation rather than by any explicit polarity configuration.
        configureDefaultPort(self, dut, portA)

    def main(self):
        # ART 6010_ART_interface_test/library_6010.py lines 29-51
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 14: On the copper test port now running with an automatically resolved role, record the resolved polarity from 'show interface <port>' and the polarity configuration from 'show running-config interface <port>'. Then apply 'interface <port>', 'shutdown', wait for the port to go down, apply 'no shutdown' and wait for the link to return.")

        dut.mode('#')
        before_interface = dut.cmd('show interface {}'.format(portA.name))
        before_running_config = dut.cmd('show running-config interface {}'.format(portA.name))
        output = 'show interface before:\n{}\nshow running-config interface before:\n{}'.format(
            before_interface, before_running_config)
        self.log('OBSERVED: {}'.format(output))

        resolved_polarity_before = None
        for line in before_interface.splitlines():
            if 'current polarity' in line:
                for field in line.split(','):
                    field = field.strip()
                    if field.startswith('current polarity'):
                        resolved_polarity_before = field.split()[-1]

        polarity_config_before = None
        for line in before_running_config.splitlines():
            if 'polarity' in line:
                polarity_config_before = line.strip()

        if resolved_polarity_before is None:
            self.failed('show interface {} did not report a current polarity value to record'.format(portA.name))
            return
        else:
            self.passed('recorded resolved polarity {} on {} before the shutdown/no shutdown cycle'.format(
                resolved_polarity_before, portA.name))

        if checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'auto'):
            self.passed('{} polarity configuration remains auto (unconfigured) before the cycle'.format(portA.name))
        else:
            self.failed('{} polarity configuration is not the expected auto default before the cycle'.format(
                portA.name))
            return

        status_before = dut.cmd('show interface {} status'.format(portA.name))
        row_before = next(
            (line for line in status_before.splitlines() if line.split()[:1] == [portA.name]), None)
        if row_before is not None and 'connected' in row_before:
            self.passed('{} is connected before the shutdown/no shutdown cycle'.format(portA.name))
        else:
            self.failed('{} is not connected before the shutdown/no shutdown cycle: {}'.format(
                portA.name, row_before))
            return

        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('shutdown')
        dut.mode('#')
        time.sleep(3)

        status_down = dut.cmd('show interface {} status'.format(portA.name))
        row_down = next(
            (line for line in status_down.splitlines() if line.split()[:1] == [portA.name]), None)
        if row_down is not None and 'connected' not in row_down:
            self.passed('{} left the connected state after shutdown: {}'.format(portA.name, row_down))
        else:
            self.failed('{} still shows connected after shutdown: {}'.format(portA.name, row_down))
            return

        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('no shutdown')
        dut.mode('#')
        time.sleep(5)

        status_after = dut.cmd('show interface {} status'.format(portA.name))
        row_after = next(
            (line for line in status_after.splitlines() if line.split()[:1] == [portA.name]), None)
        if row_after is not None and 'connected' in row_after:
            self.passed('{} returned to connected after no shutdown: {}'.format(portA.name, row_after))
        else:
            self.failed('{} did not return to connected after no shutdown: {}'.format(portA.name, row_after))
            return

        after_interface = dut.cmd('show interface {}'.format(portA.name))
        resolved_polarity_after = None
        for line in after_interface.splitlines():
            if 'current polarity' in line:
                for field in line.split(','):
                    field = field.strip()
                    if field.startswith('current polarity'):
                        resolved_polarity_after = field.split()[-1]

        if resolved_polarity_after == resolved_polarity_before:
            self.passed('{} resolved current polarity {} is unchanged after the shutdown/no shutdown cycle'.format(
                portA.name, resolved_polarity_after))
        else:
            self.failed('{} resolved current polarity changed from {} to {} after the cycle'.format(
                portA.name, resolved_polarity_before, resolved_polarity_after))
            return

        after_running_config = dut.cmd('show running-config interface {}'.format(portA.name))
        polarity_config_after = None
        for line in after_running_config.splitlines():
            if 'polarity' in line:
                polarity_config_after = line.strip()

        if polarity_config_after == polarity_config_before:
            self.passed(
                '{} polarity configuration in show running-config interface unchanged: {}'.format(
                    portA.name, polarity_config_after))
        else:
            self.failed(
                '{} polarity configuration changed from {} to {} in show running-config interface'.format(
                    portA.name, polarity_config_before, polarity_config_after))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Mirror configure(): leave portA at its default speed/duplex/polarity, the same
        # state configure() established, whatever the shutdown/no shutdown cycle resolved.
        configureDefaultPort(self, dut, portA)


class TestCase_14(ATTestCase.TestCase):
    testCaseDesc = "On the same copper test port, exercise polarity and duplex changes in sequence: 'duplex full' then 'polarity mdi'; 'shutdown' then 'no shutdown'; 'duplex auto' then 'polarity auto'; 'polarity mdix' then 'duplex full'; finally 'polarity auto' and 'duplex auto'. Read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' after each pair."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "On the same copper test port, exercise polarity and duplex changes in sequence: 'duplex full' then 'polarity mdi'; 'shutdown' then 'no shutdown'; 'duplex auto' then 'polarity auto'; 'polarity mdix' then 'duplex full'; finally 'polarity auto' and 'duplex auto'. Read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' after each pair.\n"
    testCaseMethod += "Verify: Every command is accepted with no CLI error in the order issued; after each pair 'show running-config interface <port>' reflects exactly the last applied duplex and polarity values, and 'show interface <port>' reports a current duplex and current polarity consistent with that configuration (forced values match the configuration; with auto set, 'show interface <port> status' shows an auto-negotiated duplex such as 'a-full' and a resolved polarity of mdi or mdix).\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Establish the known baseline this step presumes: speed/duplex/polarity all at
        # their factory defaults and the port enabled, so the sequence of pairs below
        # starts from a defined state regardless of what an earlier, already-torn-down
        # case left behind.
        configureDefaultPort(self, dut, portA)
        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('no shutdown')
        dut.mode('#')

    def main(self):
        # legacy 5000_mdi_mdix/test-5000.0001-CopperFixed_Straight.py lines 642-718
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 15: On the same copper test port, exercise polarity and duplex changes in sequence: 'duplex full' then 'polarity mdi'; 'shutdown' then 'no shutdown'; 'duplex auto' then 'polarity auto'; 'polarity mdix' then 'duplex full'; finally 'polarity auto' and 'duplex auto'. Read 'show running-config interface <port>', 'show interface <port>' and 'show interface <port> status' after each pair.")

        def apply_pair(cmds, label):
            dut.mode(')#')
            dut.cmd('interface {}'.format(portA.name))
            combined = ''
            for cmd in cmds:
                combined += dut.cmd(cmd)
            dut.mode('#')
            self.log('OBSERVED: {} -> {}'.format(label, combined))
            if ('Invalid input' in combined or 'Unrecognized command' in combined or
                    "Can't find interface" in combined):
                self.failed('{} commands rejected by the CLI: {}'.format(label, combined))
                return False
            self.passed('{} commands accepted with no CLI error'.format(label))
            return True

        # Pair 1: duplex full then polarity mdi
        if not apply_pair(['duplex full', 'polarity mdi'], 'duplex full / polarity mdi'):
            return

        running = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(running))
        if 'duplex full' in running and 'polarity mdi' in running and 'polarity mdix' not in running:
            self.passed('show running-config interface reflects duplex full and polarity mdi')
        else:
            self.failed('show running-config interface does not reflect duplex full/polarity mdi: {}'.format(
                running))
            return

        if checkConfiguredPort(self, dut, portA, 'full', 'auto', 'mdi'):
            self.passed('show interface configured duplex/polarity match duplex full, polarity mdi')
        else:
            self.failed('show interface configured duplex/polarity do not match duplex full, polarity mdi')
            return

        dut.mode('#')
        interfaceOut = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(interfaceOut))
        if 'current duplex full' in interfaceOut and 'current polarity mdi' in interfaceOut:
            self.passed(
                'show interface reports current duplex full and current polarity mdi, matching the forced '
                'configuration')
        else:
            self.failed('show interface does not report current duplex full/current polarity mdi: {}'.format(
                interfaceOut))
            return

        statusOut = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: {}'.format(statusOut))

        # Pair 2: shutdown then no shutdown
        if not apply_pair(['shutdown'], 'shutdown'):
            return
        dut.mode('#')
        shutOut = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(shutOut))
        if 'administrative state is DOWN' in shutOut:
            self.passed('show interface reports administrative state is DOWN after shutdown')
        else:
            self.failed('show interface does not report administrative state is DOWN after shutdown: {}'.format(
                shutOut))
            return

        if not apply_pair(['no shutdown'], 'no shutdown'):
            return
        time.sleep(3)
        dut.mode('#')
        noShutOut = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(noShutOut))
        if 'administrative state is UP' in noShutOut:
            self.passed('show interface reports administrative state is UP after no shutdown')
        else:
            self.failed('show interface does not report administrative state is UP after no shutdown: {}'.format(
                noShutOut))
            return

        if checkConfiguredPort(self, dut, portA, 'full', 'auto', 'mdi'):
            self.passed('duplex full and polarity mdi configuration retained across the shutdown/no shutdown cycle')
        else:
            self.failed('duplex full/polarity mdi configuration was lost across the shutdown/no shutdown cycle')
            return

        statusOut = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: {}'.format(statusOut))

        # Pair 3: duplex auto then polarity auto
        if not apply_pair(['duplex auto', 'polarity auto'], 'duplex auto / polarity auto'):
            return

        running = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(running))
        if 'duplex full' not in running and 'polarity mdi' not in running:
            self.passed('show running-config interface no longer shows the forced duplex full/polarity mdi '
                        'settings')
        else:
            self.failed('show running-config interface still shows forced duplex full/polarity mdi settings: '
                        '{}'.format(running))
            return

        if checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'auto'):
            self.passed('show interface configured duplex/polarity match duplex auto, polarity auto')
        else:
            self.failed('show interface configured duplex/polarity do not match duplex auto, polarity auto')
            return

        dut.mode('#')
        statusOut = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: {}'.format(statusOut))
        row = next((line for line in statusOut.splitlines() if line.split()[:1] == [portA.name]), None)
        if row is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        if 'a-full' in row or 'a-half' in row:
            self.passed('show interface status reports an auto-negotiated duplex for {}: {}'.format(
                portA.name, row))
        else:
            self.failed('show interface status does not report an auto-negotiated duplex for {}: {}'.format(
                portA.name, row))
            return
        if 'mdi' in row:
            self.passed('show interface status reports a resolved polarity (mdi/mdix) for {}: {}'.format(
                portA.name, row))
        else:
            self.failed('show interface status does not report a resolved polarity for {}: {}'.format(
                portA.name, row))
            return

        # Pair 4: polarity mdix then duplex full
        if not apply_pair(['polarity mdix', 'duplex full'], 'polarity mdix / duplex full'):
            return

        running = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(running))
        if 'polarity mdix' in running and 'duplex full' in running:
            self.passed('show running-config interface reflects polarity mdix and duplex full')
        else:
            self.failed('show running-config interface does not reflect polarity mdix/duplex full: {}'.format(
                running))
            return

        if checkConfiguredPort(self, dut, portA, 'full', 'auto', 'mdix'):
            self.passed('show interface configured duplex/polarity match duplex full, polarity mdix')
        else:
            self.failed('show interface configured duplex/polarity do not match duplex full, polarity mdix')
            return

        dut.mode('#')
        interfaceOut = dut.cmd('show interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(interfaceOut))
        if 'current duplex full' in interfaceOut and 'current polarity mdix' in interfaceOut:
            self.passed(
                'show interface reports current duplex full and current polarity mdix, matching the forced '
                'configuration')
        else:
            self.failed('show interface does not report current duplex full/current polarity mdix: {}'.format(
                interfaceOut))
            return

        statusOut = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: {}'.format(statusOut))

        # Pair 5 (final): polarity auto and duplex auto
        if not apply_pair(['polarity auto', 'duplex auto'], 'polarity auto / duplex auto'):
            return

        running = dut.cmd('show running-config interface {}'.format(portA.name))
        self.log('OBSERVED: {}'.format(running))
        if 'polarity mdix' not in running and 'duplex full' not in running:
            self.passed('show running-config interface no longer shows the forced polarity mdix/duplex full '
                        'settings')
        else:
            self.failed('show running-config interface still shows forced polarity mdix/duplex full settings: '
                        '{}'.format(running))
            return

        if checkConfiguredPort(self, dut, portA, 'auto', 'auto', 'auto'):
            self.passed('show interface configured duplex/polarity match duplex auto, polarity auto')
        else:
            self.failed('show interface configured duplex/polarity do not match duplex auto, polarity auto')
            return

        dut.mode('#')
        statusOut = dut.cmd('show interface {} status'.format(portA.name))
        self.log('OBSERVED: {}'.format(statusOut))
        row = next((line for line in statusOut.splitlines() if line.split()[:1] == [portA.name]), None)
        if row is None:
            self.failed('port {} missing from show interface status output'.format(portA.name))
            return
        if 'a-full' in row or 'a-half' in row:
            self.passed('show interface status reports an auto-negotiated duplex for {}: {}'.format(
                portA.name, row))
        else:
            self.failed('show interface status does not report an auto-negotiated duplex for {}: {}'.format(
                portA.name, row))
            return
        if 'mdi' in row:
            self.passed('show interface status reports a resolved polarity (mdi/mdix) for {}: {}'.format(
                portA.name, row))
        else:
            self.failed('show interface status does not report a resolved polarity for {}: {}'.format(
                portA.name, row))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Mirror configure(): return the port to its factory default speed/duplex/polarity
        # and ensure it is enabled, undoing every command main() applied during the
        # sequence of pairs.
        configureDefaultPort(self, dut, portA)
        dut.mode(')#')
        dut.cmd('interface {}'.format(portA.name))
        dut.cmd('no shutdown')
        dut.mode('#')


class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = "Prompt the operator to insert a copper SFP module into a pluggable-capable port on the DUT and connect it with a straight-through cable to the partner port; then poll 'show interface <port> status' and 'show system pluggable' until the module is detected."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "Prompt the operator to insert a copper SFP module into a pluggable-capable port on the DUT and connect it with a straight-through cable to the partner port; then poll 'show interface <port> status' and 'show system pluggable' until the module is detected.\n"
    testCaseMethod += "Verify: Operator confirms insertion; 'show system pluggable' lists the module in the SFP port and identifies it as a copper/1000BASE-T transceiver; 'show interface <port> status' transitions to 'connected' within the link-up timeout.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Precondition: the pluggable-capable port under test and its partner are
        # brought back to default auto-negotiation (speed/duplex/polarity) and left
        # enabled, so the module the operator inserts can negotiate freely.
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)

    def main(self):
        # ART 6000_link_check/library_6000.py lines 657-691
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 16: Prompt the operator to insert a copper SFP module into a pluggable-capable port on the DUT and connect it with a straight-through cable to the partner port; then poll 'show interface <port> status' and 'show system pluggable' until the module is detected.")
        # PHYSICAL: the operator acts on the hardware, then we poll for the state change.
        port = portPeer
        self.log("OPERATOR: insert a copper SFP module into {} and connect it with a straight-through cable to partner port {}, then confirm the swap is complete.".format(port.name, portDut.name))
        want_status = 'connected'
        want_type = '1000BASE-T'
        deadline = time.time() + 120
        status_output = ''
        pluggable_output = ''
        detected = False
        while time.time() < deadline:
            dut.mode('#')
            # Scoped to ONE port, so a plain substring test here is safe.
            status_output = dut.cmd('show interface {} status'.format(port.name), log=False)
            pluggable_output = dut.cmd('show system pluggable {}'.format(port.name), log=False)
            if want_status in status_output and want_type in pluggable_output:
                detected = True
                break
            self.log('Waiting for operator: module insertion/connection into {} not yet detected.'.format(port.name))
            time.sleep(2)
        self.log('OBSERVED: show system pluggable {}:\n{}\nshow interface {} status:\n{}'.format(
            port.name, pluggable_output, port.name, status_output))

        if want_type not in pluggable_output:
            self.failed(
                "'show system pluggable' did not list a copper/1000BASE-T transceiver on {} within "
                "the link-up timeout".format(port.name))
            return
        else:
            self.passed(
                "'show system pluggable' identifies the module in {} as a copper/1000BASE-T "
                "transceiver".format(port.name))

        if want_status in status_output:
            self.passed(
                "'show interface {} status' transitioned to connected within the link-up "
                "timeout".format(port.name))
        else:
            self.failed(
                "'show interface {} status' did not reach connected within the link-up "
                "timeout".format(port.name))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Mirror configure(): return both ends of the link to default
        # auto-negotiation, undoing any settings the operator or main() left behind.
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)


class TestCase_16(ATTestCase.TestCase):
    testCaseDesc = "With the copper SFP module linked to the partner over a straight-through cable and polarity left at the default automatic setting on both ends, read 'show interface <SFP port>' on the DUT and 'show interface <partner port>' on the partner."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "With the copper SFP module linked to the partner over a straight-through cable and polarity left at the default automatic setting on both ends, read 'show interface <SFP port>' on the DUT and 'show interface <partner port>' on the partner.\n"
    testCaseMethod += "Verify: The SFP port link is up; 'show interface <SFP port>' reports a resolved current polarity of mdi or mdix for the copper SFP port, and the partner reports the complementary role — automatic crossover resolution works over the copper SFP module as it does on a fixed copper port. Where the platform does not report polarity for a pluggable copper port, record that the field is not presented rather than asserting a value.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # This step presumes both ends are still at the factory default (auto)
        # polarity/speed/duplex over the straight-through copper SFP link.
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)

    def main(self):
        # legacy 5000_mdi_mdix/library_5000.py lines 207-238
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 17: With the copper SFP module linked to the partner over a straight-through cable and polarity left at the default automatic setting on both ends, read 'show interface <SFP port>' on the DUT and 'show interface <partner port>' on the partner.")

        dut.mode('#')
        dutOutput = dut.cmd('show interface {}'.format(portPeer.name))
        peer.mode('#')
        peerOutput = peer.cmd('show interface {}'.format(portDut.name))
        self.log('OBSERVED: DUT show interface {}: {}\nPartner show interface {}: {}'.format(
            portPeer.name, dutOutput, portDut.name, peerOutput))

        if 'Link is UP' not in dutOutput:
            self.failed('DUT port {} show interface does not report Link is UP: {}'.format(
                portPeer.name, dutOutput))
            return
        self.passed('DUT SFP port {} link is UP'.format(portPeer.name))

        dut_polarity_line = next(
            (line.strip() for line in dutOutput.splitlines() if 'current polarity' in line), None)

        if dut_polarity_line is None:
            self.log('INFO: DUT does not present a current polarity field for pluggable copper '
                      'port {}; recording as not presented rather than asserting a value'.format(
                          portPeer.name))
            self.passed('DUT port {} current polarity field is not presented on this platform, '
                        'recorded as not applicable'.format(portPeer.name))
            return

        dut_polarity = dut_polarity_line.split('current polarity')[-1].strip().rstrip(',')
        if dut_polarity not in ('mdi', 'mdix'):
            self.failed('DUT port {} resolved current polarity is {}, expected mdi or mdix'.format(
                portPeer.name, dut_polarity))
            return
        self.passed('DUT SFP port {} resolved current polarity is {}'.format(
            portPeer.name, dut_polarity))

        peer_polarity_line = next(
            (line.strip() for line in peerOutput.splitlines() if 'current polarity' in line), None)

        if peer_polarity_line is None:
            self.log('INFO: partner does not present a current polarity field for port {}; '
                      'recording as not presented rather than asserting a value'.format(portDut.name))
            self.passed('Partner port {} current polarity field is not presented on this platform, '
                        'recorded as not applicable'.format(portDut.name))
            return

        peer_polarity = peer_polarity_line.split('current polarity')[-1].strip().rstrip(',')
        complementary = {'mdi': 'mdix', 'mdix': 'mdi'}
        if peer_polarity == complementary.get(dut_polarity):
            self.passed('Partner port {} resolved complementary polarity {} to DUT polarity {}'.format(
                portDut.name, peer_polarity, dut_polarity))
        else:
            self.failed('Partner port {} resolved polarity {}, expected complementary {} to DUT '
                        'polarity {}'.format(
                            portDut.name, peer_polarity, complementary.get(dut_polarity), dut_polarity))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # main() only performed reads; restore both ends to the default (auto)
        # configuration established in configure(), mirroring it exactly.
        configureDefaultPort(self, dut, portPeer)
        configureDefaultPort(self, peer, portDut)


class TestCase_17(ATTestCase.TestCase):
    testCaseDesc = "Prompt the operator to insert a fibre SFP module into a pluggable-capable port on the DUT and connect it to a matching fibre partner port; then poll 'show system pluggable' and 'show interface <fibre port> status' until the module is recognised and the link is up."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "Prompt the operator to insert a fibre SFP module into a pluggable-capable port on the DUT and connect it to a matching fibre partner port; then poll 'show system pluggable' and 'show interface <fibre port> status' until the module is recognised and the link is up.\n"
    testCaseMethod += "Verify: Operator confirms insertion; 'show system pluggable' identifies the module as a fibre transceiver and 'show interface <fibre port> status' reads 'connected'.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Physical-media step: no device configuration is presumed beyond the suite's
        # own configure(); the port is brought up by the operator inserting the module.
        pass

    def main(self):
        # ART 6000_link_check/library_6000.py lines 657-691
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 18: Prompt the operator to insert a fibre SFP module into a pluggable-capable port on the DUT and connect it to a matching fibre partner port; then poll 'show system pluggable' and 'show interface <fibre port> status' until the module is recognised and the link is up.")
        # PHYSICAL: the pluggable-capable port on this topology is the fibre neighbour
        # link (dut.portPeer <-> peer.portDut) - the operator swaps its SFP for a
        # fibre module and reconnects the partner end.
        port = portPeer
        self.log('OPERATOR: insert a fibre SFP module into {} on the DUT, connect it to {} on '
                 'the partner switch, then confirm the link.'.format(port.name, portDut.name))
        want = 'connected'
        deadline = time.time() + 120
        output = ''
        row = None
        while time.time() < deadline:
            # Scoped to ONE port row from show interface status.
            output = dut.cmd('show interface {} status'.format(port.name), log=False)
            row = next((line for line in output.splitlines()
                        if line.split()[:1] == [port.name]), None)
            if row is not None and want in row:
                break
            self.log('Waiting for operator to insert fibre SFP module and bring up '
                      'link on {}'.format(port.name))
            time.sleep(2)
        self.log('OBSERVED: {}'.format(output))

        if row is not None and want in row:
            self.passed('{} show interface status row reads connected: {}'.format(port.name, row))
        else:
            self.failed('{} show interface status did not reach connected: {}'.format(port.name, row))
            return

        pluggable_output = dut.cmd('show system pluggable {}'.format(port.name))
        self.log('OBSERVED: {}'.format(pluggable_output))
        plug_row = next((line for line in pluggable_output.splitlines()
                          if line.split()[:1] == [port.name]), None)
        if plug_row is None:
            self.failed('{} missing from show system pluggable output'.format(port.name))
            return

        type_field = plug_row.split()[-1]
        if 'BASE' in type_field and not type_field.endswith('-T'):
            self.passed('show system pluggable identifies {} as a fibre transceiver: {}'.format(
                port.name, type_field))
        else:
            self.failed('show system pluggable did not identify {} as a fibre transceiver: {}'.format(
                port.name, type_field))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Physical-media step: no device configuration was applied by main() to revert;
        # the operator-driven pluggable swap is left for the next case's own precondition.
        pass


class TestCase_18(ATTestCase.TestCase):
    testCaseDesc = "Record the fibre SFP port's link state from 'show interface <fibre port> status', then attempt to apply polarity configuration to it: 'interface <fibre port>' then 'polarity mdi', and again 'polarity mdix'. Capture the CLI response to each, then re-read 'show running-config interface <fibre port>' and 'show interface <fibre port> status'."
    testCaseRef = 'AWPTCM-T33234'
    testCaseMethod = "Record the fibre SFP port's link state from 'show interface <fibre port> status', then attempt to apply polarity configuration to it: 'interface <fibre port>' then 'polarity mdi', and again 'polarity mdix'. Capture the CLI response to each, then re-read 'show running-config interface <fibre port>' and 'show interface <fibre port> status'.\n"
    testCaseMethod += "Verify: The DUT reports the setting as not applicable to this media type — either the command is rejected with an error or a message indicating polarity is not supported on fibre media, rather than being accepted silently; 'show running-config interface <fibre port>' shows no forced polarity applied where the command was refused; 'show interface <fibre port> status' reads 'connected' both before and after the attempts, confirming no change to link state. Where the platform accepts the command on a fibre port but ignores it, record that 'show interface <fibre port>' presents no resolved mdi/mdix role for the fibre media.\n"

    def configure(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Ensure the fibre SFP port starts this step at its default polarity/speed/duplex
        # settings, undisturbed by any earlier case's leftover configuration.
        configureDefaultPort(self, dut, portPeer)

    def main(self):
        # legacy 5703_Speed_Duplex_Polarity/test-5000.1003.py lines 228-262 (py2→py3)
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        self.log("STEP 19: Record the fibre SFP port's link state from 'show interface <fibre port> status', then attempt to apply polarity configuration to it: 'interface <fibre port>' then 'polarity mdi', and again 'polarity mdix'. Capture the CLI response to each, then re-read 'show running-config interface <fibre port>' and 'show interface <fibre port> status'.")

        dut.mode('#')
        status_before = dut.cmd('show interface {} status'.format(portPeer.name))
        self.log('OBSERVED: {}'.format(status_before))

        before_row = next((line for line in status_before.splitlines()
                            if line.split()[:1] == [portPeer.name]), None)
        if before_row is None or 'connected' not in before_row:
            self.failed('fibre port {} not reading connected before polarity attempts: {}'.format(
                portPeer.name, status_before))
            return
        else:
            self.passed('fibre port {} status is connected before polarity attempts'.format(portPeer.name))

        dut.mode(')#')
        dut.cmd('interface {}'.format(portPeer.name))
        response_mdi = dut.cmd('polarity mdi')
        response_mdix = dut.cmd('polarity mdix')
        dut.mode('#')

        self.log('OBSERVED: polarity mdi response: {}'.format(response_mdi))
        self.log('OBSERVED: polarity mdix response: {}'.format(response_mdix))

        rejected_mdi = ('Invalid input' in response_mdi or '% Invalid' in response_mdi
                        or 'not supported' in response_mdi.lower()
                        or 'not applicable' in response_mdi.lower())
        rejected_mdix = ('Invalid input' in response_mdix or '% Invalid' in response_mdix
                         or 'not supported' in response_mdix.lower()
                         or 'not applicable' in response_mdix.lower())

        running_config = dut.cmd('show running-config interface {}'.format(portPeer.name))
        self.log('OBSERVED: {}'.format(running_config))

        if rejected_mdi and rejected_mdix:
            self.passed('polarity mdi/mdix rejected on fibre port {}: mdi response {!r}, mdix response {!r}'.format(
                portPeer.name, response_mdi.strip(), response_mdix.strip()))
            if 'polarity mdi' in running_config or 'polarity mdix' in running_config:
                self.failed('fibre port {} running-config shows forced polarity despite command rejection: {}'.format(
                    portPeer.name, running_config))
            else:
                self.passed('fibre port {} running-config shows no forced polarity applied, as expected'.format(
                    portPeer.name))
        else:
            if 'polarity mdi' in running_config or 'polarity mdix' in running_config:
                self.failed('polarity command accepted and applied on fibre port {}, running-config: {}'.format(
                    portPeer.name, running_config))
                return
            show_int = dut.cmd('show interface {}'.format(portPeer.name))
            self.log('OBSERVED: {}'.format(show_int))
            if 'polarity mdi' in show_int or 'polarity mdix' in show_int:
                self.failed('fibre port {} presents a resolved mdi/mdix role despite fibre media: {}'.format(
                    portPeer.name, show_int))
            else:
                self.passed(
                    'polarity command accepted but ignored on fibre port {}: '
                    'no resolved mdi/mdix role reported'.format(portPeer.name))

        status_after = dut.cmd('show interface {} status'.format(portPeer.name))
        self.log('OBSERVED: {}'.format(status_after))
        after_row = next((line for line in status_after.splitlines()
                           if line.split()[:1] == [portPeer.name]), None)
        if after_row is not None and 'connected' in after_row:
            self.passed('fibre port {} status remains connected after polarity attempts'.format(portPeer.name))
        else:
            self.failed('fibre port {} status changed after polarity attempts: {}'.format(
                portPeer.name, status_after))

    def tear_down(self):
        tb = self.testSet.tb
        dut = self.testSet.dut
        ethA = tb.ethA
        portA = dut.portA
        peer = self.testSet.peer
        portPeer = dut.portPeer
        portDut = peer.portDut
        # Restore the fibre SFP port to default speed/duplex/polarity in case the
        # platform silently accepted the polarity mdi/mdix commands applied in main().
        configureDefaultPort(self, dut, portPeer)


